  const stack = [];
  let count = 0;
  for (const num of nums) {
    while (stack.length > 0 && stack[stack.length - 1][0] < num) {
      stack.pop();
    }
    if (stack.length > 0 && stack[stack.length - 1][0] === num) {
      stack[stack.length - 1][1]++;
    } else {
      stack.push([num, 1]);
    }
    count += stack[stack.length - 1][1];
  }
